import {
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import {
  getAnchoredLayerPosition,
  type AnchoredAlign,
  type AnchoredSide,
} from "./anchored-layer";
import { useBalsaPortalScope } from "./BalsaPortalScope";
import { Button } from "./Button";
import { mergeClasses } from "./classes";
import { roundedClasses, type Rounded } from "./form";
import { MenuList, type MenuListHandle } from "./MenuList";
import type { MenuItem, MenuSelection, MenuVariant } from "./menu";
import {
  capturePortalPresentation,
  type PortalPresentationSnapshot,
} from "./portal-core";
import type { Shadow, ThemeInput, ThemePresentation } from "./theme";
import {
  BalsaThemeContext,
  useControllableState,
  useResolvedThemeProps,
} from "./theme-context";
import type { ActionColor } from "./types";

export interface DropdownMenuProps extends Omit<
  HTMLAttributes<HTMLElement>,
  "children" | "id" | "onSelect"
> {
  id: string;
  label: string;
  items: readonly MenuItem[];
  side?: AnchoredSide;
  align?: AnchoredAlign;
  sideOffset?: number;
  variant?: MenuVariant;
  color?: ActionColor;
  rounded?: Rounded;
  shadow?: Shadow;
  contained?: boolean;
  disabled?: boolean;
  theme?: ThemeInput;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  onSelect?: (selection: MenuSelection) => void;
  trigger?: ReactNode;
  "data-balsa"?: string;
  "data-palette"?: string;
}

export function DropdownMenu(rawProps: DropdownMenuProps) {
  const { props, theme } = useResolvedThemeProps("dropdown-menu", "overlays", rawProps, {
    variant: "surface",
    rounded: "lg",
    shadow: "auto",
  } as const);
  const {
    id,
    label,
    items,
    side = "bottom",
    align = "start",
    sideOffset = 8,
    variant,
    color = "primary",
    rounded,
    shadow,
    contained = false,
    disabled = false,
    theme: _themeInput,
    open,
    defaultOpen = false,
    onOpenChange,
    onSelect,
    trigger,
    "data-balsa": _dataBalsa,
    "data-palette": dataPalette,
    className,
    style,
    onKeyDown,
    ...domProps
  } = props;
  void _themeInput;
  void _dataBalsa;

  const [current, setOpen] = useControllableState({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });
  const scope = useBalsaPortalScope();
  const rootRef = useRef<HTMLSpanElement | null>(null);
  const panelRef = useRef<HTMLDivElement | null>(null);
  const listRef = useRef<MenuListHandle | null>(null);
  const [mounted, setMounted] = useState(false);
  const [resolvedSide, setResolvedSide] = useState<AnchoredSide>(side);
  const [position, setPosition] = useState({ left: 0, top: 0, maxHeight: 0 });
  const [portalSnapshot, setPortalSnapshot] = useState<PortalPresentationSnapshot | null>(null);
  const themeRef = useRef(theme);
  themeRef.current = theme;
  const openRef = useRef(current);
  openRef.current = current;

  const showPanel = mounted && current;
  const portalHost = contained ? null : (scope?.host ?? (mounted ? document.body : null));

  function triggerElement(): HTMLButtonElement | null {
    return rootRef.current?.querySelector<HTMLButtonElement>(":scope > button") ?? null;
  }

  function close(restoreFocus = true): void {
    setOpen(false);
    if (restoreFocus) queueMicrotask(() => triggerElement()?.focus());
  }

  function capturePresentation(): void {
    const root = rootRef.current;
    if (!root?.isConnected) return;
    const currentTheme = themeRef.current;
    const presentation: ThemePresentation | undefined =
      currentTheme.inherited || currentTheme.explicitPresentation
        ? currentTheme.presentation
        : undefined;
    try {
      const snapshot = capturePortalPresentation(root, presentation);
      setPortalSnapshot((currentSnapshot) => (
        currentSnapshot
          && currentSnapshot.themeId === snapshot.themeId
          && currentSnapshot.themeBase === snapshot.themeBase
          && currentSnapshot.paletteId === snapshot.paletteId
          && currentSnapshot.adapt === snapshot.adapt
          ? currentSnapshot
          : snapshot
      ));
    } catch {
      setPortalSnapshot((currentSnapshot) => currentSnapshot);
    }
  }

  function updatePosition(): void {
    const triggerNode = triggerElement();
    const panelNode = panelRef.current;
    if (!triggerNode || !panelNode || !openRef.current) return;
    const next = getAnchoredLayerPosition(triggerNode, panelNode, {
      side,
      align,
      sideOffset,
      alignOffset: 0,
    });
    const rootRect = rootRef.current?.getBoundingClientRect();
    const left = next.left - (contained ? rootRect?.left ?? 0 : 0);
    const top = next.top - (contained ? rootRect?.top ?? 0 : 0);
    setPosition((currentPosition) => (
      currentPosition.left === left
        && currentPosition.top === top
        && currentPosition.maxHeight === next.maxHeight
        ? currentPosition
        : { left, top, maxHeight: next.maxHeight }
    ));
    setResolvedSide((currentSide) => currentSide === next.side ? currentSide : next.side);
  }

  function handleSelection(selection: MenuSelection): void {
    onSelect?.(selection);
    close();
  }

  function handleTriggerKeydown(event: KeyboardEvent<HTMLButtonElement>): void {
    if (["ArrowDown", "Enter", " "].includes(event.key)) {
      event.preventDefault();
      setOpen(true);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      setOpen(true);
      queueMicrotask(() => {
        const buttons = panelRef.current?.querySelectorAll<HTMLElement>('[role^="menuitem"]');
        buttons?.item(buttons.length - 1)?.focus();
      });
    }
    onKeyDown?.(event as KeyboardEvent<HTMLElement>);
  }

  useLayoutEffect(() => {
    setMounted(true);
  }, []);

  useLayoutEffect(() => {
    if (!showPanel) return;
    capturePresentation();
    updatePosition();
    listRef.current?.focusFirst();
  }, [showPanel, side, align, sideOffset, contained]);

  useLayoutEffect(() => {
    if (!mounted) return;

    function handleDocumentPointer(event: PointerEvent): void {
      if (!openRef.current) return;
      const target = event.target as Node;
      if (rootRef.current?.contains(target) || panelRef.current?.contains(target)) return;
      close(false);
    }

    document.addEventListener("pointerdown", handleDocumentPointer, true);
    window.addEventListener("resize", updatePosition, { passive: true });
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      document.removeEventListener("pointerdown", handleDocumentPointer, true);
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [mounted, contained, side, align, sideOffset]);

  const panelPresentation = portalSnapshot ?? {
    themeId: theme.presentation.id,
    themeBase: theme.presentation.base,
    paletteId: dataPalette,
    style: Object.fromEntries(
      Object.entries(theme.presentation.style).filter(([property]) => property.startsWith("--balsa-")),
    ) as PortalPresentationSnapshot["style"],
  };
  const triggerClasses = mergeClasses(
    "border-balsa-border-strong bg-balsa-surface px-balsa-md py-balsa-2xs text-balsa-surface-foreground hover:bg-balsa-muted",
    rawProps.rounded === undefined ? "rounded-balsa-control" : roundedClasses[rounded],
    className,
  );
  const panelStyle = {
    left: `${position.left}px`,
    top: `${position.top}px`,
    maxHeight: `${position.maxHeight}px`,
    ...panelPresentation.style,
  } as CSSProperties;
  const panel = showPanel ? (
    <div
      ref={panelRef}
      data-balsa="dropdown-menu-panel"
      data-theme={panelPresentation.themeId}
      data-theme-base={panelPresentation.themeBase}
      data-palette={dataPalette ?? panelPresentation.paletteId}
      data-side={resolvedSide}
      data-shadow={shadow}
      className={mergeClasses("z-[65]", contained ? "absolute" : "fixed")}
      style={panelStyle}
    >
      <MenuList
        id={id}
        ref={listRef}
        label={label}
        items={items}
        variant={variant}
        color={color}
        rounded={rounded}
        shadow={shadow}
        data-palette={dataPalette ?? panelPresentation.paletteId}
        onSelect={handleSelection}
        onDismiss={() => close()}
      />
    </div>
  ) : null;

  return (
    <BalsaThemeContext.Provider value={theme}>
      <span
        {...domProps}
        ref={rootRef}
        data-balsa="dropdown-menu"
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-palette={dataPalette}
        data-color={color}
        data-rounded={rounded}
        data-state={current ? "open" : "closed"}
        className="relative inline-flex"
        style={{
          ...theme.explicitPresentation?.style,
          ...style,
        } as CSSProperties}
      >
        <Button
          id={`${id}-trigger`}
          variant="outline"
          color="neutral"
          size="md"
          disabled={disabled}
          aria-expanded={current}
          aria-controls={id}
          aria-haspopup="menu"
          className={triggerClasses}
          onClick={() => {
            if (!disabled) setOpen(!current);
          }}
          onKeyDown={handleTriggerKeydown}
        >
          {trigger ?? "Open menu"}
        </Button>
        {contained ? panel : (portalHost && panel ? createPortal(panel, portalHost) : null)}
      </span>
    </BalsaThemeContext.Provider>
  );
}

import { Check, ChevronRight, Circle } from "lucide-react";
import {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
  type CSSProperties,
  type ForwardRefExoticComponent,
  type HTMLAttributes,
  type KeyboardEvent,
  type RefAttributes,
} from "react";
import { mergeClasses } from "./classes";
import { roundedClasses, type Rounded } from "./form";
import { Icon } from "./Icon";
import {
  isInteractiveMenuItem,
  type MenuItem,
  type MenuSelection,
  type MenuVariant,
} from "./menu";
import type { Shadow, ThemeInput } from "./theme";
import { BalsaThemeContext, useResolvedThemeProps } from "./theme-context";
import type { ActionColor } from "./types";

export interface MenuListHandle {
  focusFirst: () => void;
}

export interface MenuListProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "children" | "id" | "onSelect"
> {
  id: string;
  label: string;
  items: readonly MenuItem[];
  variant?: MenuVariant;
  color?: ActionColor;
  rounded?: Rounded;
  shadow?: Shadow;
  theme?: ThemeInput;
  submenu?: boolean;
  "data-balsa"?: string;
  "data-palette"?: string;
  onSelect?: (selection: MenuSelection) => void;
  onDismiss?: () => void;
  onCloseSubmenu?: () => void;
}

const variantClasses: Readonly<Record<MenuVariant, string[]>> = {
  surface: ["border-balsa-border-strong bg-balsa-surface-elevated text-balsa-surface-elevated-foreground"],
  outline: ["border-balsa-border-strong bg-balsa-background text-balsa-foreground"],
  soft: ["border-balsa-border bg-balsa-muted text-balsa-foreground"],
  glass: ["border-balsa-border/70 text-balsa-surface-foreground backdrop-balsa"],
};

const colorClasses: Readonly<Record<ActionColor, Record<MenuVariant, string[]>>> = {
  neutral: { surface: [], outline: [], soft: [], glass: [] },
  primary: {
    surface: ["border-balsa-primary/30"],
    outline: ["border-balsa-primary"],
    soft: ["border-balsa-primary/20", "bg-balsa-primary/10"],
    glass: ["border-balsa-primary/30"],
  },
  secondary: {
    surface: ["border-balsa-secondary/30"],
    outline: ["border-balsa-secondary"],
    soft: ["border-balsa-secondary/20", "bg-balsa-secondary/10"],
    glass: ["border-balsa-secondary/30"],
  },
  accent: {
    surface: ["border-balsa-accent/30"],
    outline: ["border-balsa-accent"],
    soft: ["border-balsa-accent/20", "bg-balsa-accent/10"],
    glass: ["border-balsa-accent/30"],
  },
  destructive: {
    surface: ["border-balsa-destructive/30"],
    outline: ["border-balsa-destructive"],
    soft: ["border-balsa-destructive/20", "bg-balsa-destructive/10"],
    glass: ["border-balsa-destructive/30"],
  },
};

function firstInteractiveIndex(items: readonly MenuItem[]): number {
  const index = items.findIndex(isInteractiveMenuItem);
  return index < 0 ? 0 : index;
}

function lastInteractiveIndex(items: readonly MenuItem[]): number {
  const reversed = [...items].reverse().findIndex(isInteractiveMenuItem);
  return reversed < 0 ? 0 : items.length - reversed - 1;
}

function itemRole(item: MenuItem): "menuitem" | "menuitemcheckbox" | "menuitemradio" {
  if (item.type === "checkbox") return "menuitemcheckbox";
  if (item.type === "radio") return "menuitemradio";
  return "menuitem";
}

export const MenuList: ForwardRefExoticComponent<
  MenuListProps & RefAttributes<MenuListHandle>
> = forwardRef<MenuListHandle, MenuListProps>(function MenuListInner(
  rawProps,
  forwardedRef,
) {
  const { props, theme } = useResolvedThemeProps("dropdown-menu", "overlays", rawProps, {
    variant: "surface",
    rounded: "lg",
    shadow: "auto",
  } as const);
  const {
    id,
    label,
    items,
    variant,
    color,
    rounded,
    shadow,
    theme: _themeInput,
    submenu = false,
    "data-balsa": _dataBalsa,
    "data-palette": dataPalette,
    className,
    style,
    onSelect,
    onDismiss,
    onCloseSubmenu,
    ...domProps
  } = props;
  void _themeInput;
  void _dataBalsa;

  const rootRef = useRef<HTMLDivElement | null>(null);
  const typeaheadRef = useRef("");
  const typeaheadTimerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const [activeIndex, setActiveIndex] = useState(() => firstInteractiveIndex(items));
  const [openSubmenuIndex, setOpenSubmenuIndex] = useState<number | null>(null);

  function focusIndex(index: number): void {
    queueMicrotask(() => {
      rootRef.current
        ?.querySelector<HTMLElement>(`[data-menu-index="${index}"]`)
        ?.focus();
    });
  }

  function focusFirst(): void {
    const index = firstInteractiveIndex(items);
    setActiveIndex(index);
    focusIndex(index);
  }

  useImperativeHandle(forwardedRef, () => ({ focusFirst }));

  useEffect(() => () => {
    clearTimeout(typeaheadTimerRef.current);
  }, []);

  function moveActive(direction: 1 | -1): void {
    if (!items.some(isInteractiveMenuItem)) return;
    let next = activeIndex;
    do {
      next = (next + direction + items.length) % items.length;
    } while (!isInteractiveMenuItem(items[next]!));
    setActiveIndex(next);
    focusIndex(next);
  }

  function selectItem(item: MenuItem, index: number): void {
    if (!isInteractiveMenuItem(item)) return;
    setActiveIndex(index);
    if (item.type === "submenu" || item.children?.length) {
      setOpenSubmenuIndex(index);
      return;
    }
    onSelect?.({
      id: item.id,
      type: item.type === "checkbox"
        ? "checkbox"
        : item.type === "radio"
          ? "radio"
          : "action",
      value: item.value,
      checked: item.type === "checkbox" ? !item.checked : item.checked,
    });
  }

  function handleKeydown(event: KeyboardEvent<HTMLButtonElement>, item: MenuItem, index: number): void {
    if (event.key === "ArrowDown") {
      event.preventDefault();
      moveActive(1);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      moveActive(-1);
    } else if (event.key === "Home") {
      event.preventDefault();
      const next = firstInteractiveIndex(items);
      setActiveIndex(next);
      focusIndex(next);
    } else if (event.key === "End") {
      event.preventDefault();
      const next = lastInteractiveIndex(items);
      setActiveIndex(next);
      focusIndex(next);
    } else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      selectItem(item, index);
    } else if (event.key === "ArrowRight" && (item.children?.length || item.type === "submenu")) {
      event.preventDefault();
      setOpenSubmenuIndex(index);
    } else if (event.key === "ArrowLeft" && submenu) {
      event.preventDefault();
      onCloseSubmenu?.();
    } else if (event.key === "Escape") {
      event.preventDefault();
      onDismiss?.();
    } else if (event.key.length === 1 && /\S/.test(event.key)) {
      typeaheadRef.current += event.key.toLocaleLowerCase();
      clearTimeout(typeaheadTimerRef.current);
      typeaheadTimerRef.current = setTimeout(() => {
        typeaheadRef.current = "";
      }, 500);
      const match = items.findIndex((candidate) =>
        isInteractiveMenuItem(candidate)
        && candidate.label?.toLocaleLowerCase().startsWith(typeaheadRef.current));
      if (match >= 0) {
        setActiveIndex(match);
        focusIndex(match);
      }
    }
  }

  const rootClasses = mergeClasses(
    "min-w-52 max-w-[min(22rem,calc(100vw-1rem))] overflow-y-auto border p-balsa-3xs shadow-balsa-panel outline-none",
    roundedClasses[rounded],
    submenu ? "absolute left-full top-0 z-[70] ml-balsa-3xs" : "",
    variantClasses[variant],
    color ? colorClasses[color][variant] : [],
    className,
  );

  return (
    <BalsaThemeContext.Provider value={theme}>
      <div
        {...domProps}
        id={id}
        ref={rootRef}
        data-balsa="menu-list"
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-palette={dataPalette}
        data-variant={variant}
        data-color={color}
        data-rounded={rounded}
        data-shadow={shadow}
        role="menu"
        aria-label={label}
        className={rootClasses}
        style={{
          ...theme.explicitPresentation?.style,
          ...style,
        } as CSSProperties}
      >
        {items.map((item, index) => {
          if (item.type === "separator") {
            return (
              <div
                key={item.id}
                className="my-balsa-3xs h-px bg-balsa-border"
                role="separator"
              />
            );
          }
          if (item.type === "label") {
            return (
              <div
                key={item.id}
                className="px-balsa-md py-balsa-xs text-xs font-medium uppercase tracking-wider text-balsa-muted-foreground"
                role="presentation"
              >
                {item.label}
              </div>
            );
          }

          const active = index === activeIndex;
          const hasSubmenu = Boolean(item.children?.length);
          return (
            <div key={item.id} className="relative">
              <button
                type="button"
                data-menu-index={index}
                role={itemRole(item)}
                tabIndex={active ? 0 : -1}
                disabled={item.disabled}
                aria-checked={item.type === "checkbox" || item.type === "radio"
                  ? item.checked
                  : undefined}
                aria-haspopup={hasSubmenu ? "menu" : undefined}
                aria-expanded={hasSubmenu ? openSubmenuIndex === index : undefined}
                className={mergeClasses(
                  "relative flex min-h-9 w-full items-center gap-balsa-xs rounded-md px-balsa-md py-balsa-xs text-left text-sm outline-none transition-colors",
                  active
                    ? item.destructive
                      ? "bg-balsa-destructive text-balsa-destructive-foreground"
                      : "bg-balsa-selected text-balsa-selected-foreground"
                    : item.destructive
                      ? "text-balsa-destructive"
                      : "text-inherit",
                  item.disabled ? "cursor-not-allowed opacity-50" : "cursor-pointer",
                )}
                onFocus={() => setActiveIndex(index)}
                onPointerEnter={() => setActiveIndex(index)}
                onClick={() => selectItem(item, index)}
                onKeyDown={(event) => handleKeydown(event, item, index)}
              >
                {item.icon ? <Icon icon={item.icon} size="md" /> : null}
                <span
                  className="min-w-0 flex-1 truncate"
                  style={item.labelFontFamily ? { fontFamily: item.labelFontFamily } : undefined}
                >
                  {item.label}
                </span>
                {item.type === "checkbox" && item.checked
                  ? <Icon icon={Check} size="md" />
                  : item.type === "radio" && item.checked
                    ? <Icon icon={Circle} size="sm" className="fill-current" />
                    : null}
                {item.shortcut
                  ? <span className="ml-balsa-lg text-xs text-current/70">{item.shortcut}</span>
                  : null}
                {hasSubmenu ? <Icon icon={ChevronRight} size="md" /> : null}
              </button>
              {hasSubmenu && openSubmenuIndex === index ? (
                <MenuList
                  id={`${id}-${item.id}`}
                  label={item.label ?? label}
                  items={item.children ?? []}
                  variant={variant}
                  color={color}
                  rounded={rounded}
                  shadow={shadow}
                  data-palette={dataPalette}
                  submenu
                  onSelect={onSelect}
                  onDismiss={onDismiss}
                  onCloseSubmenu={() => setOpenSubmenuIndex(null)}
                />
              ) : null}
            </div>
          );
        })}
      </div>
    </BalsaThemeContext.Provider>
  );
});

import {
  useRef,
  type CSSProperties,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
} from "react";
import type { AnchoredAlign, AnchoredSide } from "./anchored-layer";
import { mergeClasses } from "./classes";
import { DropdownMenu } from "./DropdownMenu";
import { roundedClasses, type Rounded } from "./form";
import { Icon, type IconComponent } from "./Icon";
import type { MenuItem, MenuSelection, MenuVariant } from "./menu";
import type { Shadow, ThemeInput } from "./theme";
import { BalsaThemeContext, useResolvedThemeProps } from "./theme-context";

export interface PropertySelectProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "children" | "id" | "onSelect"
> {
  id: string;
  label: string;
  value?: string;
  items?: readonly MenuItem[];
  icon?: IconComponent;
  /** Renders the value in its own family, for font pickers. */
  valueFontFamily?: string;
  side?: AnchoredSide;
  align?: AnchoredAlign;
  sideOffset?: number;
  disabled?: boolean;
  variant?: MenuVariant;
  rounded?: Rounded;
  shadow?: Shadow;
  theme?: ThemeInput;
  trailing?: ReactNode;
  onSelect?: (selection: MenuSelection) => void;
  onActivate?: () => void;
  "data-balsa"?: string;
  "data-palette"?: string;
}

export function PropertySelect(rawProps: PropertySelectProps) {
  const { props, theme } = useResolvedThemeProps("dropdown-menu", "overlays", rawProps, {
    variant: "surface",
    rounded: "lg",
    shadow: "auto",
  } as const);
  const {
    id,
    label,
    value,
    items,
    icon,
    valueFontFamily,
    side = "bottom",
    align = "start",
    sideOffset = 8,
    disabled = false,
    variant,
    rounded,
    shadow,
    theme: _themeInput,
    trailing,
    onSelect,
    onActivate,
    "data-balsa": _dataBalsa,
    "data-palette": dataPalette,
    className,
    style,
    onClick,
    ...domProps
  } = props;
  void _themeInput;
  void _dataBalsa;

  const trailingHostRef = useRef<HTMLSpanElement | null>(null);
  const hasMenu = Boolean(items?.length);
  const controlClasses = mergeClasses(
    "flex w-full min-w-0 cursor-pointer items-center justify-start gap-0 overflow-hidden border border-balsa-border bg-balsa-surface p-0 text-left text-sm font-semibold text-balsa-surface-foreground transition-colors hover:bg-balsa-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-balsa-focus-ring focus-within:outline-2 focus-within:outline-offset-2 focus-within:outline-balsa-focus-ring",
    rawProps.rounded === undefined ? "rounded-balsa-control" : roundedClasses[rounded],
    disabled ? "cursor-not-allowed bg-balsa-disabled text-balsa-disabled-foreground" : "",
    className,
  );
  const valueStyle = valueFontFamily ? { fontFamily: valueFontFamily } : undefined;
  const content = (
    <>
      <span className="min-w-0 flex-1 py-balsa-xs pl-balsa-md">
        <small className="block text-xs font-normal text-balsa-muted-foreground">{label}</small>
        <strong className="block truncate" style={valueStyle}>{value}</strong>
      </span>
      {trailing ?? (icon
        ? <Icon icon={icon} size="md" className="mr-balsa-md shrink-0 self-center" />
        : null)}
    </>
  );

  function forwardToTrailing(event: MouseEvent<HTMLDivElement>): void {
    onClick?.(event);
    if (event.defaultPrevented || disabled) return;
    const target = event.target as Node | null;
    if (target && trailingHostRef.current?.contains(target)) return;
    onActivate?.();
    trailingHostRef.current
      ?.querySelector<HTMLElement>("button, [role='button'], input")
      ?.click();
  }

  if (hasMenu) {
    return (
      <DropdownMenu
        id={id}
        label={label}
        items={items ?? []}
        side={side}
        align={align}
        sideOffset={sideOffset}
        variant={variant}
        rounded={rawProps.rounded}
        shadow={shadow}
        disabled={disabled}
        theme={rawProps.theme}
        data-palette={dataPalette}
        className={controlClasses}
        style={style}
        trigger={content}
        onSelect={onSelect}
      />
    );
  }

  return (
    <BalsaThemeContext.Provider value={theme}>
      <div
        {...domProps}
        id={id}
        data-balsa="property-select"
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-palette={dataPalette}
        data-rounded={rounded}
        className={controlClasses}
        style={{
          ...theme.explicitPresentation?.style,
          ...style,
        } as CSSProperties}
        onClick={forwardToTrailing}
      >
        <span className="min-w-0 flex-1 py-balsa-xs pl-balsa-md" aria-hidden="true">
          <small className="block text-xs font-normal text-balsa-muted-foreground">{label}</small>
          <strong className="block truncate" style={valueStyle}>{value}</strong>
        </span>
        <span ref={trailingHostRef} className="contents">
          {trailing ?? (icon
            ? <Icon icon={icon} size="md" className="mr-balsa-md shrink-0 self-center" />
            : null)}
        </span>
      </div>
    </BalsaThemeContext.Provider>
  );
}

